namespace TF2SA.Data.Analytics.PlayerDetail;

/// <summary>
/// A row of <c>player_summary(steamid)</c>. Property names resolve to the macro's
/// column aliases case-insensitively. Not an EF entity — no MariaDB table backs it.
/// </summary>
public class PlayerSummaryRow
{
	public ulong SteamId { get; set; }
	public string? PlayerName { get; set; }
	public string? Avatar { get; set; }

	/// <summary>Hand-authored, not generated by the app — see
	/// scripts/player-narrative-facts.sql. Null until authored.</summary>
	public string? Description { get; set; }
	public int NumberOfGames { get; set; }
	public int Wins { get; set; }
	public int Draws { get; set; }
	public int Losses { get; set; }
	public float? WinPercentage { get; set; }
	public float? AverageDpm { get; set; }
	public float? AverageKills { get; set; }
	public float? AverageDeaths { get; set; }
	public float? AverageAssists { get; set; }
	public float? AverageAirshots { get; set; }
}
